           #{chartOfAccountId},
           #{branchId}
         );

mapper.update:
UPDATE chart_accounts SET
      is_active = 2,
      modified = NOW(),
      modified_by = #{userId}
WHERE id = #{id};

UPDATE chart_accounts SET
    is_active = #{statusId},
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id};

mapper.select:
SELECT
  id AS id,
  CONCAT(chart_accounts.account_codes, '-', chart_accounts.account_description) AS accountDescription
FROM chart_accounts
WHERE chart_accounts.is_active < 2


      AND parent_id = #{parentId}


      AND parent_id IS NULL



    AND chart_accounts.chart_account_type_id = #{filter.accountTypeId}


    AND chart_accounts.chart_account_group_id = #{filter.accountGroupId}

LIMIT #{filter.page}, #{filter.rowsPerPage}
